/* Speech Therapy English — V13 consolidated application logic */
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const STORE={notebook:'steNotebook',mastered:'steMastered',flash:'steFlashStatsV4',searchHistory:'steDictionaryHistoryV7',diagnosticHistory:'steDiagnosticHistoryV9',practiceHistory:'stePracticeHistoryV10',sprintHistory:'steSprintHistoryV10',lastPage:'steLastLearningPageV13'};
let st={scale:+localStorage.scale||1,theme:localStorage.theme||"light",contrast:localStorage.contrast||"normal",simple:localStorage.simple==="true",motion:localStorage.motion==="true"};
let notebook=[],mastered=[],flashStats={},lexiconUpdate=()=>{},flashReset=()=>{},practiceMake=()=>{},dictionaryFlashIds=[];

function apply(){document.documentElement.style.setProperty("--scale",st.scale);document.documentElement.dataset.theme=st.theme;document.documentElement.dataset.contrast=st.contrast;document.body.classList.toggle("simple",st.simple);document.body.classList.toggle("reduce-motion",st.motion)}
function saveA11y(){localStorage.scale=st.scale;localStorage.theme=st.theme;localStorage.contrast=st.contrast;localStorage.simple=st.simple;localStorage.motion=st.motion;apply()}
function initA11y(){apply();$("#aMinus").onclick=()=>{st.scale=Math.max(.85,st.scale-.1);saveA11y()};$("#aPlus").onclick=()=>{st.scale=Math.min(1.7,st.scale+.1);saveA11y()};$("#dark").onclick=()=>{st.theme=st.theme==="dark"?"light":"dark";saveA11y()};$("#contrast").onclick=()=>{st.contrast=st.contrast==="high"?"normal":"high";saveA11y()};$("#simple").onclick=()=>{st.simple=!st.simple;saveA11y()};$("#motion").onclick=()=>{st.motion=!st.motion;saveA11y()}}
function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m]))}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function speak(t){if(!("speechSynthesis"in window))return alert("Speech synthesis is not supported.");speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(t);u.lang="en-GB";u.rate=.78;speechSynthesis.speak(u)}
function loadArray(key){try{const x=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(x)?x:[]}catch{return []}}
function loadObject(key){try{const x=JSON.parse(localStorage.getItem(key)||'{}');return x&&typeof x==='object'&&!Array.isArray(x)?x:{}}catch{return {}}}
function saveFlashStats(){localStorage.setItem(STORE.flash,JSON.stringify(flashStats))}
function saveNotebookState(){localStorage.setItem(STORE.notebook,JSON.stringify(notebook));localStorage.setItem(STORE.mastered,JSON.stringify(mastered));updateNotebookUI()}
function validIds(ids){const allowed=new Set(VOCABULARY.map(v=>v.id));return [...new Set(ids)].filter(id=>allowed.has(id))}
function isSaved(id){return notebook.includes(id)}function isMastered(id){return mastered.includes(id)}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1800)}
function toggleSave(id){if(isSaved(id)){notebook=notebook.filter(x=>x!==id);mastered=mastered.filter(x=>x!==id);toast('Removed from My Vocabulary');}else{notebook.push(id);toast('Saved to My Vocabulary ♥')}saveNotebookState();syncWordButtons(id);renderNotebook()}
function toggleMastered(id){if(isMastered(id)){mastered=mastered.filter(x=>x!==id);toast('Marked for review ↻')}else{if(!isSaved(id))notebook.push(id);mastered.push(id);toast('Marked as mastered ✓')}saveNotebookState();syncWordButtons(id);renderNotebook()}
function syncWordButtons(id){$$(`[data-save-id="${CSS.escape(id)}"]`).forEach(b=>{const on=isSaved(id);b.classList.toggle('saved',on);b.textContent=on?'♥ Saved':'♡ Save'});$$(`[data-master-id="${CSS.escape(id)}"]`).forEach(b=>{const on=isMastered(id);b.classList.toggle('mastered',on);b.textContent=on?'✓ Mastered':'Mark as mastered'});$$(`[data-term-id="${CSS.escape(id)}"]`).forEach(c=>{c.classList.toggle('saved',isSaved(id));c.classList.toggle('mastered',isMastered(id))})}
function wordActions(v){return `<button class="save-button ${isSaved(v.id)?'saved':''}" data-save-id="${esc(v.id)}">${isSaved(v.id)?'♥ Saved':'♡ Save'}</button><button class="master-button ${isMastered(v.id)?'mastered':''}" data-master-id="${esc(v.id)}">${isMastered(v.id)?'✓ Mastered':'Mark as mastered'}</button>`}
function card(v,compact=false){let lv=["A2","B1","B2","C1"].map(l=>v.levels[l]?`<div class="level"><b>${l}</b><p>${esc(v.levels[l])}</p><p><em>${esc(v.examples[l]||"")}</em></p></div>`:"").join("");return `<article class="term-card ${isSaved(v.id)?'saved':''} ${isMastered(v.id)?'mastered':''}" data-term-id="${esc(v.id)}"><h3>${esc(v.term)}</h3><p><span class="badge">Chapter ${v.chapter}</span><span class="badge">${esc(v.section)}</span><span class="badge">${esc(v.ipa)}</span><span class="badge fr">${esc(v.french)}</span></p><p>${esc(v.levels.B2||v.levels.B1||v.levels.A2||"")}</p>${compact?"":`<div class="level-grid">${lv}</div><div class="grid"><div><h4>Collocations</h4><ul>${(v.collocations||[]).map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div><div><h4>Related terms</h4><ul>${(v.related||[]).map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div></div>`}<div class="card-actions"><button data-speak="${esc(v.term)}">🔊 Listen</button><button data-toggle-french>FR on/off</button>${wordActions(v)}</div></article>`}
function showPage(id){$$('.page').forEach(p=>p.classList.remove('active'));const page=$('#'+id);if(!page)return;page.classList.add('active');$$('nav button[data-page]').forEach(b=>{const active=b.dataset.page===id;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$$('.nav-menu-group').forEach(d=>{d.classList.toggle('has-active',!!d.querySelector('button.active'));d.open=false});if(id!=='home'&&id!=='sprint')localStorage.setItem(STORE.lastPage,id);if(id==='home'&&typeof renderContinueLearning==='function')renderContinueLearning();if(id==='notebook')renderNotebook();if(id==='progress'&&typeof renderProgress==='function')renderProgress();window.scrollTo(0,0)}
function focusTerm(v){showPage('lexicon');$('#query').value=v.term;lexiconUpdate();setTimeout(()=>$('#results')?.scrollIntoView({behavior:st.motion?'auto':'smooth',block:'start'}),30)}

function updateHomeProgress(){const review=notebook.filter(id=>!mastered.includes(id)).length;$('#homeSaved').textContent=notebook.length;$('#homeMastered').textContent=mastered.length;$('#homeReview').textContent=review;$('#navSavedCount').textContent=notebook.length;$('#notebookSaved').textContent=notebook.length;$('#notebookMastered').textContent=mastered.length;$('#notebookReview').textContent=review}
function renderSpotlight(v,label='Word of the day'){const box=$('#wordSpotlight');box.querySelector('.spotlight-label').textContent=label;$('#spotlightContent').innerHTML=`<div class="spotlight-term">${esc(v.term)}</div><div class="spotlight-ipa">${esc(v.ipa)}</div><div class="spotlight-fr">${esc(v.french)}</div><div class="spotlight-definition">${esc(v.levels.B1||v.levels.A2||v.levels.B2||'')}</div><div class="spotlight-actions"><button data-speak="${esc(v.term)}">🔊 Listen</button><button data-save-id="${esc(v.id)}">${isSaved(v.id)?'♥ Saved':'♡ Save'}</button><button data-focus-id="${esc(v.id)}">Open term →</button></div>`}
function dateIndex(){const d=new Date();return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000)}
function renderFiveWords(){const pool=shuffle(VOCABULARY).slice(0,5);const q=$('#quickWords');q.hidden=false;q.innerHTML=`<h3>✨ Five words for right now</h3><div class="word-chip-grid">${pool.map(v=>`<button class="word-chip" data-focus-id="${esc(v.id)}"><strong>${esc(v.term)}</strong><span>${esc(v.french)}</span></button>`).join('')}</div>`;q.scrollIntoView({behavior:st.motion?'auto':'smooth',block:'nearest'})}
function startQuickRevision(){const sel=$('#flashChapter');const review=typeof sourceDeck==='function'?sourceDeck('__review'):[];sel.value=review.length?'__review':(notebook.length?'__saved':'');showPage('flashcards');flashReset()}
const CONTINUE_META={
  lexicon:['📚','Keep exploring the Lexicon','Browse clinical terms by topic, chapter or level.'],
  search:['🔎','Return to the Dictionary','Look up a term and follow its clinical connections.'],
  pronunciation:['🎧','Continue Pronunciation','Pick up another short pronunciation workout.'],
  flashcards:['🧠','Continue your Flashcards','Bring difficult terms back while they are still fresh.'],
  practice:['⚡','Continue Practice','Do another short round with immediate feedback.'],
  test:['📊','Check your progress again','Use the 24-question Check-up when you want a broader snapshot.'],
  cases:['🩺','Return to Clinical Cases','Apply vocabulary to another patient situation.'],
  communication:['💬','Continue Clinical Communication','Practise explaining, handing over, asking and writing.'],
  notebook:['♥','Review My Vocabulary','Revisit the terms you chose to keep.'],
  progress:['📈','Open your learning plan','Use your local activity to choose a focused next step.']
};
function learningEvidence(){
  const flash=Object.values(flashStats).some(x=>(x?.ratings||0)>0),practice=loadArray(STORE.practiceHistory).length,diag=loadArray(STORE.diagnosticHistory).length,sprint=loadArray(STORE.sprintHistory).length,comm=Object.keys(loadObject('steCommunicationProgressV11')).length,pron=Object.values(loadObject('stePronunciationStatsV12')).some(x=>x?.seen),cases=Object.keys(caseProgress||{}).length;
  return notebook.length||flash||practice||diag||sprint||comm||pron||cases;
}
function inferContinuePage(){const allowed=new Set(Object.keys(CONTINUE_META)),saved=localStorage.getItem(STORE.lastPage);if(allowed.has(saved))return saved;if(notebook.length)return'notebook';if(loadArray(STORE.practiceHistory).length)return'practice';if(Object.values(flashStats).some(x=>(x?.ratings||0)>0))return'flashcards';if(loadArray(STORE.diagnosticHistory).length)return'progress';return'lexicon'}
function renderStarterWords(){const names=['Swallowing','Aspiration','Aphasia','AAC','Dysphonia'],pool=names.map(n=>VOCABULARY.find(v=>v.term===n)).filter(Boolean),q=$('#quickWords');q.hidden=false;q.innerHTML=`<h3>🚀 Five core terms to get your bearings</h3><p class="quick-words-intro">One swallowing term, one safety term, two communication concepts and one voice term.</p><div class="word-chip-grid">${pool.map(v=>`<button class="word-chip" data-focus-id="${esc(v.id)}"><strong>${esc(v.term)}</strong><span>${esc(v.french)}</span></button>`).join('')}</div>`;q.scrollIntoView({behavior:st.motion?'auto':'smooth',block:'nearest'})}
function renderContinueLearning(){const page=inferContinuePage(),m=CONTINUE_META[page]||CONTINUE_META.lexicon,title=$('#continueLearningTitle'),text=$('#continueLearningText'),btn=$('#continueLearningAction'),card=$('#continueLearningCard');if(!title||!text||!btn)return;const has=!!learningEvidence();card?.classList.toggle('is-new',!has);title.textContent=has?`${m[0]} ${m[1]}`:'Your learning trail starts here.';text.textContent=has?m[2]:'Start with a handful of core terms, then let the site guide you towards practice and clinical use.';btn.textContent=has?'Continue →':'Open the Lexicon →';btn.dataset.target=has?page:'lexicon'}

function initHome(){const chapters=[...new Set(VOCABULARY.map(v=>v.chapter))].sort((a,b)=>Number(a)-Number(b)),sections=new Set(VOCABULARY.map(v=>v.section).filter(Boolean)).size;$('#statTerms').textContent=VOCABULARY.length;$('#statChapters').textContent=chapters.length;$('#statSections').textContent=sections;const greetings=['Ready for a quick vocab boost?','A few good words go a long way.','Tiny revision. Big clinical vocabulary.','Fancy a five-minute brain workout?','Pick a word. Use it. Own it.','Clinical English, but make it painless.','New day, new words — no drama.'];$('#dailyGreeting').textContent=greetings[dateIndex()%greetings.length];renderSpotlight(VOCABULARY[dateIndex()%VOCABULARY.length]);$('#learnFive').onclick=renderFiveWords;$('#quickRevision').onclick=startQuickRevision;$('#fiveMinuteBoost').onclick=()=>startFiveMinuteSprint();$('#surpriseMe').onclick=()=>renderSpotlight(VOCABULARY[Math.floor(Math.random()*VOCABULARY.length)],'Surprise word');$('#startHereWords')?.addEventListener('click',renderStarterWords);$('#startHereTour')?.addEventListener('click',()=>startFiveMinuteSprint());$('#continueLearningAction')?.addEventListener('click',e=>showPage(e.currentTarget.dataset.target||'lexicon'));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.go)));updateHomeProgress();renderContinueLearning()}

function initLexicon(){let ch=$('#chapter'),sec=$('#section'),q=$('#query'),lvl=$('#level');[...new Set(VOCABULARY.map(v=>v.chapter))].sort((a,b)=>Number(a)-Number(b)).forEach(x=>ch.innerHTML+=`<option>${x}</option>`);[...new Set(VOCABULARY.map(v=>v.section).filter(Boolean))].sort().forEach(x=>sec.innerHTML+=`<option>${esc(x)}</option>`);lexiconUpdate=function(){let query=q.value.toLowerCase();let arr=VOCABULARY.filter(v=>(!query||JSON.stringify(v).toLowerCase().includes(query))&&(!ch.value||v.chapter===ch.value)&&(!sec.value||v.section===sec.value)&&(!lvl.value||v.levels[lvl.value]));$('#count').textContent=arr.length+' result(s)';$('#results').innerHTML=arr.slice(0,180).map(v=>card(v)).join('')};[q,ch,sec,lvl].forEach(e=>e.addEventListener('input',lexiconUpdate));lexiconUpdate()}
function initSearch(){
  const input=$('#searchInput'),results=$('#searchResults'),entry=$('#dictionaryEntry'),suggestion=$('#searchSuggestion'),historyWrap=$('#searchHistoryWrap'),historyBox=$('#searchHistory'),count=$('#searchCount'),hint=$('#dictionaryMatchesHint');
  let history=loadArray(STORE.searchHistory).filter(x=>typeof x==='string').slice(0,8),current=null,currentLevel='B1';
  const norm=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,"'").replace(/[^a-z0-9À-ÿ' -]/g,' ').replace(/\s+/g,' ').trim();
  const fields=v=>({term:norm(v.term),fr:norm(v.french),section:norm(v.section),chapter:norm(v.chapterTitle),coll:norm((v.collocations||[]).join(' ')),related:norm((v.related||[]).join(' ')),body:norm([...(Object.values(v.levels||{})),...(Object.values(v.examples||{}))].join(' '))});
  const distance=(a,b)=>{a=norm(a);b=norm(b);const m=a.length,n=b.length,row=Array(n+1).fill(0).map((_,i)=>i);for(let i=1;i<=m;i++){let prev=row[0];row[0]=i;for(let j=1;j<=n;j++){const hold=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=hold}}return row[n]};
  function ranked(q){q=norm(q);if(q.length<2)return[];return VOCABULARY.map(v=>{const f=fields(v);let score=999;if(f.term===q)score=0;else if(f.fr===q)score=1;else if(f.term.startsWith(q))score=2;else if(f.fr.startsWith(q))score=3;else if(f.term.includes(q))score=4;else if(f.fr.includes(q))score=5;else if(f.section.includes(q)||f.chapter.includes(q))score=6;else if(f.coll.includes(q))score=7;else if(f.related.includes(q))score=8;else if(f.body.includes(q))score=9;return{v,score}}).filter(x=>x.score<999).sort((a,b)=>a.score-b.score||a.v.term.localeCompare(b.v.term)).map(x=>x.v)}
  function fuzzy(q){q=norm(q);if(q.length<3)return[];const max=Math.min(3,Math.max(1,Math.floor(q.length*.24)));return VOCABULARY.map(v=>({v,d:Math.min(distance(q,v.term),distance(q,v.french))})).filter(x=>x.d<=max).sort((a,b)=>a.d-b.d||a.v.term.localeCompare(b.v.term)).slice(0,4).map(x=>x.v)}
  function resolveRelated(label){const n=norm(label);return VOCABULARY.find(v=>norm(v.term)===n)||VOCABULARY.find(v=>norm(v.term).includes(n)||n.includes(norm(v.term)))}
  function addHistory(term){history=[term,...history.filter(x=>x!==term)].slice(0,8);localStorage.setItem(STORE.searchHistory,JSON.stringify(history));renderHistory()}
  function renderHistory(){historyWrap.hidden=!history.length;historyBox.innerHTML=history.map(x=>`<button type="button" data-history-term="${esc(x)}">${esc(x)}</button>`).join('')}
  function resultButton(v){return `<button type="button" class="dictionary-result ${current?.id===v.id?'selected':''}" data-dict-id="${esc(v.id)}"><span class="dictionary-result-term">${esc(v.term)}</span><span class="dictionary-result-fr">${esc(v.french)}</span><span class="dictionary-result-meta">Ch. ${v.chapter} · ${esc(v.section)}</span></button>`}
  function sameArea(v){return VOCABULARY.filter(x=>x.id!==v.id&&x.section===v.section).slice(0,6)}
  function relatedResolved(v){const seen=new Set();return (v.related||[]).map(label=>({label,match:resolveRelated(label)})).filter(x=>{const key=x.match?.id||norm(x.label);if(seen.has(key))return false;seen.add(key);return true})}
  function miniSet(v){const out=[v],ids=new Set([v.id]);relatedResolved(v).forEach(x=>{if(x.match&&!ids.has(x.match.id)){out.push(x.match);ids.add(x.match.id)}});sameArea(v).forEach(x=>{if(out.length<6&&!ids.has(x.id)){out.push(x);ids.add(x.id)}});return out.slice(0,6)}
  function renderEntry(v,level=currentLevel){current=v;currentLevel=v.levels?.[level]?level:(v.levels?.B1?'B1':Object.keys(v.levels||{})[0]||'A2');addHistory(v.term);const def=v.levels?.[currentLevel]||'',example=v.examples?.[currentLevel]||'';const rel=relatedResolved(v),area=sameArea(v);entry.innerHTML=`<article class="dictionary-card" data-term-id="${esc(v.id)}"><div class="dictionary-entry-top"><div><span class="badge">Chapter ${v.chapter}</span><span class="badge">${esc(v.chapterTitle||'')}</span><span class="badge">${esc(v.section)}</span></div><div class="dictionary-entry-status">${isMastered(v.id)?'<span class="dict-status mastered">✓ Mastered</span>':isSaved(v.id)?'<span class="dict-status saved">♥ Saved</span>':'<span class="dict-status">New</span>'}</div></div><div class="dictionary-headword"><div><h3>${esc(v.term)}</h3><p class="dictionary-ipa">${esc(v.ipa)}</p></div><button type="button" data-speak="${esc(v.term)}" class="dictionary-listen">🔊 Listen</button></div><div class="dictionary-french"><span>French</span><strong>${esc(v.french)}</strong></div><div class="dictionary-levels" role="group" aria-label="Definition level">${['A2','B1','B2','C1'].filter(l=>v.levels?.[l]).map(l=>`<button type="button" data-dict-level="${l}" class="${l===currentLevel?'active':''}" aria-pressed="${l===currentLevel?'true':'false'}">${l}</button>`).join('')}</div><section class="dictionary-definition-block"><span class="eyebrow">Definition · ${currentLevel}</span><p>${esc(def)}</p>${example?`<div class="dictionary-example"><strong>Clinical example</strong><p>${esc(example)}</p></div>`:''}</section><div class="dictionary-two-col"><section><h4>Useful collocations</h4><div class="dictionary-pills">${(v.collocations||[]).length?(v.collocations||[]).map(x=>`<span>${esc(x)}</span>`).join(''):'<span class="muted-pill">No collocations listed.</span>'}</div></section><section><h4>Related terms</h4><div class="dictionary-pills related">${rel.length?rel.map(x=>x.match?`<button type="button" data-dict-id="${esc(x.match.id)}">${esc(x.label)} →</button>`:`<span>${esc(x.label)}</span>`).join(''):'<span class="muted-pill">No related terms listed.</span>'}</div></section></div><section class="dictionary-explore"><div><span class="eyebrow">Explore the same clinical area</span><h4>${esc(v.section)}</h4></div><div class="dictionary-area-grid">${area.map(x=>`<button type="button" data-dict-id="${esc(x.id)}"><strong>${esc(x.term)}</strong><span>${esc(x.french)}</span></button>`).join('')}</div></section><div class="dictionary-actions"><button type="button" data-save-id="${esc(v.id)}" class="save-button ${isSaved(v.id)?'saved':''}">${isSaved(v.id)?'♥ Saved':'♡ Save'}</button><button type="button" data-master-id="${esc(v.id)}" class="master-button ${isMastered(v.id)?'mastered':''}">${isMastered(v.id)?'✓ Mastered':'Mark as mastered'}</button><button type="button" data-dict-practice="${esc(v.id)}">⚡ Practise this mini-set</button><button type="button" data-dict-flash="${esc(v.id)}">🧠 Revise related terms</button><button type="button" data-focus-id="${esc(v.id)}">Open in full lexicon →</button></div></article>`;renderResults(ranked(input.value));}
  function renderResults(arr){if(norm(input.value).length<2){results.innerHTML='<div class="dictionary-start"><span aria-hidden="true">⌨️</span><p>Type at least 2 characters, choose a recent search, or try a random term.</p></div>';count.textContent='';hint.textContent='Start typing to search.';suggestion.hidden=true;return}count.textContent=`${arr.length} match${arr.length===1?'':'es'}`;hint.textContent=arr.length?'Select a term to open its dictionary entry.':'No direct match.';results.innerHTML=arr.length?arr.slice(0,40).map(resultButton).join(''):'<div class="dictionary-start"><span aria-hidden="true">🤔</span><p>No direct match. Check the suggestions above.</p></div>';const fs=arr.length?[]:fuzzy(input.value);suggestion.hidden=!fs.length;suggestion.innerHTML=fs.length?`<strong>Did you mean…?</strong> ${fs.map(v=>`<button type="button" data-search-suggest="${esc(v.term)}">${esc(v.term)}</button>`).join('')}`:'';}
  function runSearch(openExact=false){const arr=ranked(input.value);renderResults(arr);const q=norm(input.value);const exact=arr.find(v=>norm(v.term)===q||norm(v.french)===q);if((openExact&&arr[0])||exact)renderEntry(exact||arr[0])}
  function randomEntry(){const v=VOCABULARY[Math.floor(Math.random()*VOCABULARY.length)];input.value=v.term;renderResults([v]);renderEntry(v);results.scrollTop=0}
  function startDictPractice(v){const pool=miniSet(v);showPage('practice');const mix=$('[data-practice-mode="mix"]');if(mix)mix.click();setTimeout(()=>startPracticeSession(pool),0)}
  function startDictFlash(v){dictionaryFlashIds=miniSet(v).map(x=>x.id);const sel=$('#flashChapter');let opt=sel.querySelector('option[value="__dictionary"]');if(!opt){opt=document.createElement('option');opt.value='__dictionary';sel.prepend(opt)}opt.textContent=`Dictionary mini-set · ${v.term}`;sel.value='__dictionary';showPage('flashcards');flashReset()}
  input.addEventListener('input',()=>runSearch(false));input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();runSearch(true)}});$('#randomDictionaryTerm').onclick=randomEntry;$('#dictionaryWelcomeRandom').onclick=randomEntry;$('#clearSearchHistory').onclick=()=>{history=[];localStorage.removeItem(STORE.searchHistory);renderHistory();toast('Dictionary history cleared')};
  $('#search').addEventListener('click',e=>{const hist=e.target.closest('[data-history-term]');if(hist){input.value=hist.dataset.historyTerm;runSearch(true);return}const sug=e.target.closest('[data-search-suggest]');if(sug){input.value=sug.dataset.searchSuggest;runSearch(true);return}const open=e.target.closest('[data-dict-id]');if(open){const v=VOCABULARY.find(x=>x.id===open.dataset.dictId);if(v){input.value=v.term;renderEntry(v);renderResults([v]);entry.scrollIntoView({behavior:st.motion?'auto':'smooth',block:'start'})}return}const lvl=e.target.closest('[data-dict-level]');if(lvl&&current){renderEntry(current,lvl.dataset.dictLevel);return}const prac=e.target.closest('[data-dict-practice]');if(prac){const v=VOCABULARY.find(x=>x.id===prac.dataset.dictPractice);if(v)startDictPractice(v);return}const fl=e.target.closest('[data-dict-flash]');if(fl){const v=VOCABULARY.find(x=>x.id===fl.dataset.dictFlash);if(v)startDictFlash(v)}});renderHistory();}


let flashQueue=[],flashHistory=[],flashBack=false,flashSessionTotal=0,flashUniqueRated=new Set(),flashSessionRatings={again:0,hard:0,got:0};
function flashMeta(id){return flashStats[id]||{score:0,lastRating:'',ratings:0,again:0,hard:0,got:0,updated:0}}
function flashNeedsReview(v){const m=flashMeta(v.id);return m.lastRating==='again'||m.lastRating==='hard'||(isSaved(v.id)&&!isMastered(v.id))}
function sourceDeck(value){if(value==='__saved')return VOCABULARY.filter(v=>isSaved(v.id));if(value==='__review')return VOCABULARY.filter(flashNeedsReview).sort((a,b)=>flashMeta(a.id).score-flashMeta(b.id).score);if(value==='__dictionary')return dictionaryFlashIds.map(id=>VOCABULARY.find(v=>v.id===id)).filter(Boolean);return VOCABULARY.filter(v=>!value||v.chapter===value)}
function flashStatus(v){const m=flashMeta(v.id);if(m.lastRating==='again'||m.score<0)return {text:'Needs review',cls:'review'};if(m.lastRating==='hard')return {text:'Learning',cls:'learning'};if(m.lastRating==='got'||m.score>0)return {text:'Got it',cls:'known'};return {text:'New',cls:''}}
