function updateFlashProgress(){const unique=Math.min(flashUniqueRated.size,flashSessionTotal),pct=flashSessionTotal?Math.round(unique/flashSessionTotal*100):0,extras=Math.max(0,flashQueue.length-(flashSessionTotal-unique));$('#flashProgress').textContent=`${unique} / ${flashSessionTotal}`;$('#flashProgressNote').textContent=flashSessionTotal?(extras?`${extras} extra review card${extras===1?'':'s'} queued`:`${flashQueue.length} card${flashQueue.length===1?'':'s'} remaining`):'Choose a deck to begin.';$('#flashProgressBar').style.width=pct+'%';$('#flashAgainCount').textContent=flashSessionRatings.again;$('#flashHardCount').textContent=flashSessionRatings.hard;$('#flashGotCount').textContent=flashSessionRatings.got}
