function rateFlash(rating){const v=flashQueue.shift();if(!v)return;const previous=flashMeta(v.id),delta=rating==='got'?1:rating==='hard'?-1:-2;flashStats[v.id]={score:Math.max(-5,Math.min(5,(previous.score||0)+delta)),lastRating:rating,ratings:(previous.ratings||0)+1,again:(previous.again||0)+(rating==='again'?1:0),hard:(previous.hard||0)+(rating==='hard'?1:0),got:(previous.got||0)+(rating==='got'?1:0),updated:Date.now()};saveFlashStats();if(typeof renderProgress==='function'&&$('#progress')?.classList.contains('active'))renderProgress();flashSessionRatings[rating]++;flashUniqueRated.add(v.id);flashPersistMastery(v,rating);if(rating==='again'){flashQueue.splice(Math.min(2,flashQueue.length),0,v);toast('Again — this one will be back soon ↻')}else if(rating==='hard'){flashQueue.splice(Math.min(4,flashQueue.length),0,v);toast('Hard — one more look later ◐')}else{toast('Got it ✓')}flashHistory.push(v);setFlashFlip(false);drawFlash()}
