let practiceMode='definition',practiceQueue=[],practiceIndex=0,practiceResults={correct:0,missed:0,streak:0,bestStreak:0},practiceMissedIds=[],practiceAnswered=false,practiceCurrent=null,practiceCurrentMode='definition',practiceAttemptedIds=[],practiceCorrectIds=[],practiceSummarySaved=false;
function practicePool(){const value=$('#practiceSource')?.value||'all';if(value==='saved')return VOCABULARY.filter(v=>isSaved(v.id));if(value==='review')return VOCABULARY.filter(v=>isSaved(v.id)&&!isMastered(v.id));if(value.startsWith('chapter:'))return VOCABULARY.filter(v=>v.chapter===value.split(':')[1]);return VOCABULARY}
