  if(mode==='french')return {lead:v.french,options:shuffle([v,...distractors]).map(o=>({value:o.id,label:o.term})),answer:v.id,answerLabel:v.term};
  if(mode==='listen')return {lead:`<button class="practice-listen-button" type="button" data-speak="${esc(v.term)}">🔊 Play the term</button><span class="practice-listen-note">You can replay it as often as you need.</span>`,html:true,options:shuffle([v,...distractors]).map(o=>({value:o.id,label:o.term})),answer:v.id,answerLabel:v.term};
