function updatePracticeBar(){const total=practiceQueue.length,shown=Math.min(practiceIndex+1,total),done=Math.min(practiceIndex,total);$('#practiceProgress').textContent=total?`Question ${shown} / ${total}`:'Question 0 / 0';$('#practiceModeMini').textContent=PRACTICE_MODES[practiceCurrentMode]?.name||PRACTICE_MODES[practiceMode].name;$('#practiceCorrect').textContent=practiceResults.correct;$('#practiceMissed').textContent=practiceResults.missed;$('#practiceStreak').textContent=practiceResults.streak;$('#practiceProgressBar').style.width=`${total?Math.round(done/total*100):0}%`}
