function practiceFeedbackMessage(correct){const good=['Nice one!','Exactly right.','That’s it!','Clinical vocab win.','Spot on.'];const bad=['Not this time.','Worth another look.','Close — keep this one moving.','Good one to revisit.'];const a=correct?good:bad;return a[Math.floor(Math.random()*a.length)]}
