function savePracticeAttempt(){if(practiceSummarySaved||!practiceAttemptedIds.length)return;practiceSummarySaved=true;let h=loadArray(STORE.practiceHistory).filter(x=>x&&typeof x==='object');const total=practiceAttemptedIds.length,correct=practiceCorrectIds.length;h.unshift({ts:Date.now(),pct:total?Math.round(correct/total*100):0,correct,total,mode:practiceMode,attemptedIds:[...practiceAttemptedIds],correctIds:[...practiceCorrectIds],missedIds:[...practiceMissedIds]});h=h.slice(0,20);localStorage.setItem(STORE.practiceHistory,JSON.stringify(h));if(typeof renderProgress==='function'&&$('#progress')?.classList.contains('active'))renderProgress()}
