function renderNotebook(){if(!$('#notebookResults'))return;const q=$('#notebookQuery').value.toLowerCase(),status=$('#notebookStatus').value,ch=$('#notebookChapter').value;let arr=VOCABULARY.filter(v=>isSaved(v.id)).filter(v=>!q||JSON.stringify(v).toLowerCase().includes(q)).filter(v=>!ch||v.chapter===ch).filter(v=>status==='all'||(status==='mastered'&&isMastered(v.id))||(status==='review'&&!isMastered(v.id)));$('#notebookCount').textContent=`${arr.length} word${arr.length===1?'':'s'} shown`;if(!notebook.length){$('#notebookResults').innerHTML=`<div class="empty-state"><div class="empty-icon">♡</div><h3>Your notebook is waiting</h3><p>Save useful terms from the lexicon, search results, flashcards or practice activities.</p><button data-go="lexicon">Find my first word →</button></div>`;return}if(!arr.length){$('#notebookResults').innerHTML=`<div class="empty-state"><div class="empty-icon">🔎</div><h3>No saved words match these filters</h3><p>Try another search or status.</p></div>`;return}$('#notebookResults').innerHTML=arr.map(v=>card(v,true)).join('')}
function exportNotebook(){if(!notebook.length)return toast('Your notebook is empty');const rows=[['English term','IPA','French','Chapter','Section','Status'],...VOCABULARY.filter(v=>isSaved(v.id)).map(v=>[v.term,v.ipa,v.french,v.chapter,v.section,isMastered(v.id)?'Mastered':'To review'])];const csv=rows.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='my-speech-therapy-vocabulary.csv';a.click();URL.revokeObjectURL(a.href)}
function initNotebook(){const ch=$('#notebookChapter');[...new Set(VOCABULARY.map(v=>v.chapter))].sort((a,b)=>Number(a)-Number(b)).forEach(x=>ch.innerHTML+=`<option value="${x}">Chapter ${x}</option>`);[$('#notebookQuery'),$('#notebookStatus'),ch].forEach(e=>e.addEventListener('input',renderNotebook));$('#reviewNotebook').onclick=()=>{if(!notebook.length)return toast('Save some words first');$('#flashChapter').value=notebook.some(id=>!mastered.includes(id))?'__review':'__saved';showPage('flashcards');flashReset()};$('#exportNotebook').onclick=exportNotebook;$('#clearNotebook').onclick=()=>{if(!notebook.length)return;if(confirm('Clear all saved words and mastered status from this browser?')){notebook=[];mastered=[];saveNotebookState();renderNotebook();toast('Notebook cleared')}};renderNotebook()}
function updateNotebookUI(){updateHomeProgress();if($('#notebookResults'))renderNotebook();const current=$('#flashChapter')?.value;if(current==='__saved'||current==='__review')flashReset()}

const DIAGNOSTIC_DOMAINS={
  '18':{name:'Dysphagia',short:'Dysphagia',icon:'🥤'},
  '19':{name:'Neurogenic Communication',short:'Neurogenic Communication',icon:'🧠'},
  '20':{name:'Voice Disorders',short:'Voice Disorders',icon:'🎙️'}
};
const DIAGNOSTIC_TYPES={
  translation:{name:'French → English',icon:'🇫🇷'},definition:{name:'Definition',icon:'🔎'},clinical:{name:'Clinical context',icon:'🩺'},collocation:{name:'Collocation',icon:'🔗'},case:{name:'Mini clinical note',icon:'📋'}
};
let diagnosticQuestions=[],diagnosticIndex=0,diagnosticAnswered=false,diagnosticStats=null,diagnosticMissedIds=[];
function diagnosticLevels(){const v=$('#diagnosticLevel')?.value||'clinical';return v==='core'?['A2','B1']:v==='advanced'?['B2','C1']:['B1','B2']}
function diagnosticText(v,kind){const levels=diagnosticLevels();for(const l of [...levels].reverse()){const x=kind==='example'?v.examples?.[l]:v.levels?.[l];if(x)return x}return kind==='example'?Object.values(v.examples||{}).find(Boolean)||'':Object.values(v.levels||{}).find(Boolean)||''}
function diagnosticRedact(text,term){let out=String(text||'');if(!term)return out;const escaped=term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');out=out.replace(new RegExp(escaped,'gi'),'_____');return out}
function diagnosticOptions(v,pool){const wrong=shuffle(pool.filter(x=>x.id!==v.id)).slice(0,3);return shuffle([v,...wrong]).map(x=>({value:x.id,label:x.term}))}
function diagnosticPick(pool,used,predicate=()=>true){let choices=pool.filter(v=>!used.has(v.id)&&predicate(v));if(!choices.length)choices=pool.filter(v=>!used.has(v.id));const v=shuffle(choices)[0]||shuffle(pool)[0];used.add(v.id);return v}
function buildDiagnosticQuestion(v,type,pool){let prompt='',clue='';
  if(type==='translation'){prompt='Which English term matches this French term?';clue=`<em>${esc(v.french)}</em>`}
  if(type==='definition'){prompt='Which term matches this definition?';clue=esc(diagnosticRedact(diagnosticText(v,'definition'),v.term))}
  if(type==='clinical'){prompt='Which term best completes this clinical context?';clue=esc(diagnosticRedact(diagnosticText(v,'example'),v.term))}
  if(type==='collocation'){const useful=(v.collocations||[]).filter(c=>String(c).toLowerCase()!==String(v.term).toLowerCase());const c=shuffle(useful)[0]||shuffle(v.collocations||[])[0]||v.term;prompt='Which term is most closely linked to this clinical collocation?';clue=`<em>${esc(diagnosticRedact(c,v.term))}</em>`}
  if(type==='case'){prompt='Which term best fits this short clinical note?';const ex=diagnosticRedact(diagnosticText(v,'example'),v.term),def=diagnosticRedact(diagnosticText(v,'definition'),v.term);clue=`<strong>Clinical note:</strong> ${esc(ex)}<br><span class="extra">${esc(def)}</span>`}
  return {v,type,prompt,clue,options:diagnosticOptions(v,pool),answer:v.id};
}
function makeDiagnostic(){const pattern=['translation','definition','clinical','collocation','case','translation','definition','case'],qs=[];for(const ch of ['18','19','20']){const pool=VOCABULARY.filter(v=>v.chapter===ch),used=new Set();pattern.forEach(type=>{let predicate=()=>true;if(type==='collocation')predicate=v=>(v.collocations||[]).some(c=>String(c).toLowerCase()!==String(v.term).toLowerCase());if(type==='clinical'||type==='case')predicate=v=>Object.values(v.examples||{}).some(Boolean);const v=diagnosticPick(pool,used,predicate);qs.push(buildDiagnosticQuestion(v,type,pool))})}return shuffle(qs)}
function freshDiagnosticStats(){return {correct:0,missed:0,byDomain:{'18':{correct:0,total:0},'19':{correct:0,total:0},'20':{correct:0,total:0}},byType:{translation:{correct:0,total:0},definition:{correct:0,total:0},clinical:{correct:0,total:0},collocation:{correct:0,total:0},case:{correct:0,total:0}}}}
function updateDiagnosticBar(){const total=diagnosticQuestions.length,q=diagnosticQuestions[diagnosticIndex];$('#diagnosticQuestionCount').textContent=diagnosticIndex<total?`Question ${diagnosticIndex+1} / ${total}`:'Complete';$('#diagnosticDomainMini').textContent=q?`${DIAGNOSTIC_DOMAINS[q.v.chapter].icon} ${DIAGNOSTIC_DOMAINS[q.v.chapter].name}`:'Progress check complete';$('#diagnosticCorrect').textContent=diagnosticStats?.correct||0;$('#diagnosticMissed').textContent=diagnosticStats?.missed||0;$('#diagnosticProgressBar').style.width=`${total?Math.round(diagnosticIndex/total*100):0}%`}
function renderDiagnosticQuestion(){if(diagnosticIndex>=diagnosticQuestions.length)return renderDiagnosticSummary();diagnosticAnswered=false;const q=diagnosticQuestions[diagnosticIndex],domain=DIAGNOSTIC_DOMAINS[q.v.chapter],type=DIAGNOSTIC_TYPES[q.type];updateDiagnosticBar();$('#testBox').innerHTML=`<article class="diagnostic-question"><div class="diagnostic-question-top"><span class="diagnostic-type">${type.icon} ${esc(type.name)}</span><span class="diagnostic-domain">${domain.icon} ${esc(domain.name)}</span></div><h3>${esc(q.prompt)}</h3><div class="diagnostic-clue">${q.clue}</div><fieldset class="diagnostic-options"><legend class="sr-only">Choose one answer</legend>${q.options.map((o,i)=>`<label class="diagnostic-option"><input type="radio" name="diagnosticAnswer" value="${esc(o.value)}"><span class="diagnostic-option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o.label)}</span></label>`).join('')}</fieldset><div class="diagnostic-question-actions"><button id="checkDiagnostic" class="primary-action">Check answer</button></div><div id="diagnosticFeedback" aria-live="polite"></div></article>`;$('#checkDiagnostic').onclick=()=>checkDiagnosticAnswer(q)}
function checkDiagnosticAnswer(q){if(diagnosticAnswered)return;const picked=$('input[name=diagnosticAnswer]:checked');if(!picked){toast('Choose an answer first');return}diagnosticAnswered=true;const correct=picked.value===q.answer;diagnosticStats.byDomain[q.v.chapter].total++;diagnosticStats.byType[q.type].total++;if(correct){diagnosticStats.correct++;diagnosticStats.byDomain[q.v.chapter].correct++;diagnosticStats.byType[q.type].correct++}else{diagnosticStats.missed++;if(!diagnosticMissedIds.includes(q.v.id))diagnosticMissedIds.push(q.v.id)}$$('.diagnostic-option').forEach(l=>{const input=$('input',l);l.classList.toggle('is-correct',input.value===q.answer);if(input.checked&&input.value!==q.answer)l.classList.add('is-wrong');input.disabled=true});const def=diagnosticText(q.v,'definition');$('#diagnosticFeedback').innerHTML=`<div class="diagnostic-feedback ${correct?'':'wrong'}"><strong>${correct?'✓ Correct':'↻ Worth revisiting'}</strong><p><b>${esc(q.v.term)}</b> · ${esc(q.v.french)}</p><p>${esc(def)}</p></div><div class="diagnostic-question-actions"><button id="nextDiagnostic" class="primary-action">${diagnosticIndex===diagnosticQuestions.length-1?'See my results →':'Next question →'}</button><button data-save-id="${esc(q.v.id)}">${isSaved(q.v.id)?'♥ Saved':'♡ Save word'}</button></div>`;updateDiagnosticBar();$('#nextDiagnostic').onclick=()=>{diagnosticIndex++;renderDiagnosticQuestion()}}
function diagnosticPct(x){return x.total?Math.round(x.correct/x.total*100):0}
function diagnosticBand(pct){return pct>=88?['Excellent clinical vocabulary base','You are retrieving terminology accurately across this check.']:pct>=75?['Strong progress','Your vocabulary is working well; targeted revision should tighten the remaining gaps.']:pct>=58?['A solid base to build on','You know a lot already. A focused revision round will make retrieval more reliable.']:['Useful diagnostic result','The gaps are now visible — which makes the next revision session much more efficient.']}
function saveDiagnosticAttempt(result){let h=loadArray(STORE.diagnosticHistory).filter(x=>x&&typeof x==='object');h.unshift(result);h=h.slice(0,5);localStorage.setItem(STORE.diagnosticHistory,JSON.stringify(h));renderDiagnosticHistory();if(typeof renderProgress==='function'&&$('#progress')?.classList.contains('active'))renderProgress()}
function renderDiagnosticHistory(){const box=$('#diagnosticHistory');if(!box)return;const h=loadArray(STORE.diagnosticHistory).filter(x=>x&&typeof x==='object').slice(0,5);if(!h.length){box.innerHTML='<p class="muted-copy">No completed progress check yet.</p>';return}box.innerHTML=h.map((a,i)=>`<article class="diagnostic-history-item"><strong>${a.pct}%</strong><span>${esc(a.levelLabel||'Clinical')}</span><small>${esc(a.dateLabel||'Previous attempt')}${i===0?' · latest':''}</small></article>`).join('')}
function diagnosticRevisionPool(){let pool=diagnosticMissedIds.map(id=>VOCABULARY.find(v=>v.id===id)).filter(Boolean);if(pool.length)return pool;const domainEntries=Object.entries(diagnosticStats.byDomain).sort((a,b)=>diagnosticPct(a[1])-diagnosticPct(b[1]));return shuffle(VOCABULARY.filter(v=>v.chapter===domainEntries[0][0])).slice(0,10)}
function startDiagnosticRevision(){const pool=diagnosticRevisionPool();showPage('practice');const mix=$('[data-practice-mode="mix"]');if(mix)mix.click();setTimeout(()=>startPracticeSession(pool),0)}
function renderDiagnosticSummary(){const total=diagnosticQuestions.length,pct=Math.round(diagnosticStats.correct/total*100),band=diagnosticBand(pct),domains=Object.entries(diagnosticStats.byDomain).map(([ch,s])=>({ch,...s,pct:diagnosticPct(s)})).sort((a,b)=>b.pct-a.pct),strong=domains[0],priority=domains[domains.length-1],balanced=strong.pct===priority.pct,missed=diagnosticMissedIds.map(id=>VOCABULARY.find(v=>v.id===id)).filter(Boolean);$('#diagnosticProgressBar').style.width='100%';$('#diagnosticQuestionCount').textContent='Complete';$('#diagnosticDomainMini').textContent='Your revision map is ready';$('#diagnosticCorrect').textContent=diagnosticStats.correct;$('#diagnosticMissed').textContent=diagnosticStats.missed;diagnosticMissedIds.forEach(id=>{if(isSaved(id)&&isMastered(id))mastered=mastered.filter(x=>x!==id)});saveNotebookState();const levelLabel=$('#diagnosticLevel').selectedOptions[0].textContent;const now=new Date();saveDiagnosticAttempt({pct,score:diagnosticStats.correct,total,levelLabel,dateLabel:now.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}),domains:Object.fromEntries(domains.map(d=>[d.ch,d.pct])),missedIds:[...diagnosticMissedIds]});const typeHtml=Object.entries(diagnosticStats.byType).map(([k,s])=>`<span>${DIAGNOSTIC_TYPES[k].icon} ${esc(DIAGNOSTIC_TYPES[k].name)} · <b>${s.correct}/${s.total}</b></span>`).join('');$('#testBox').innerHTML=`<section class="diagnostic-summary"><div class="diagnostic-summary-hero"><div class="diagnostic-score-ring"><strong>${diagnosticStats.correct}/${total}</strong><span>${pct}% correct</span></div><div><span class="eyebrow" style="color:#fff">Progress check complete</span><h3>${band[0]}</h3><p>${band[1]}</p></div></div><div class="diagnostic-domain-results">${domains.map(d=>`<article class="diagnostic-domain-result"><div class="diagnostic-domain-result-head"><strong>${DIAGNOSTIC_DOMAINS[d.ch].icon} ${esc(DIAGNOSTIC_DOMAINS[d.ch].short)}</strong><b>${d.correct}/${d.total}</b></div><div class="diag-bar"><span style="width:${d.pct}%"></span></div><small>${d.pct}%</small></article>`).join('')}</div><div class="diagnostic-plan"><article class="diagnostic-strength"><span class="eyebrow">Strongest area</span><h4>${DIAGNOSTIC_DOMAINS[strong.ch].icon} ${esc(DIAGNOSTIC_DOMAINS[strong.ch].name)}</h4><p>${strong.pct}% in this check. Keep it active with occasional mixed practice.</p></article>${balanced?`<article class="diagnostic-priority"><span class="eyebrow">Balanced result</span><h4>⚖️ No single weak area</h4><p>All three areas scored ${priority.pct}% in this check. Keep them active with mixed practice.</p></article>`:`<article class="diagnostic-priority"><span class="eyebrow">Priority area</span><h4>${DIAGNOSTIC_DOMAINS[priority.ch].icon} ${esc(DIAGNOSTIC_DOMAINS[priority.ch].name)}</h4><p>${priority.pct}% in this check. Start your next revision session here.</p></article>`}</div><section class="diagnostic-missed"><h4>Question-type breakdown</h4><div class="diagnostic-type-breakdown">${typeHtml}</div></section>${missed.length?`<section class="diagnostic-missed"><h4>Worth another look · ${missed.length} term${missed.length===1?'':'s'}</h4><div class="diagnostic-missed-chips">${missed.map(v=>`<button data-focus-id="${esc(v.id)}">${esc(v.term)}</button>`).join('')}</div></section>`:`<section class="diagnostic-missed"><h4>Nothing in the missed-word list 🎉</h4><p>${balanced?'Use mixed practice to keep all three areas active.':'Use the priority-area recommendation above to keep the vocabulary active.'}</p></section>`}<div class="diagnostic-summary-actions"><button id="buildDiagnosticRevision" class="primary-action">⚡ Build me a revision session</button>${missed.length?'<button id="saveDiagnosticMissed">♡ Save weak words</button>':''}<button id="retakeDiagnostic">↻ Take another check</button></div><p class="diagnostic-disclaimer">This is a vocabulary-learning progress check, not a clinical competence assessment or formal examination.</p></section>`;$('#buildDiagnosticRevision').onclick=startDiagnosticRevision;$('#saveDiagnosticMissed')?.addEventListener('click',()=>{missed.forEach(v=>{if(!notebook.includes(v.id))notebook.push(v.id);mastered=mastered.filter(id=>id!==v.id)});saveNotebookState();toast(`${missed.length} word${missed.length===1?'':'s'} saved for review ♥`)});$('#retakeDiagnostic').onclick=()=>{startDiagnostic()}}
function startDiagnostic(){diagnosticQuestions=makeDiagnostic();diagnosticIndex=0;diagnosticAnswered=false;diagnosticStats=freshDiagnosticStats();diagnosticMissedIds=[];$('#diagnosticIntro').hidden=true;$('#diagnosticSession').hidden=false;renderDiagnosticQuestion();$('#diagnosticSession').scrollIntoView({behavior:st.motion?'auto':'smooth',block:'start'})}
function initTest(){renderDiagnosticHistory();$('#startDiagnostic').onclick=startDiagnostic;$('#clearDiagnosticHistory').onclick=()=>{const h=loadArray(STORE.diagnosticHistory);if(!h.length)return toast('No progress-check history to clear');if(confirm('Clear previous progress-check results from this browser?')){localStorage.removeItem(STORE.diagnosticHistory);renderDiagnosticHistory();toast('Progress-check history cleared')}}}


function initGlobalActions(){document.addEventListener('click',e=>{const save=e.target.closest('[data-save-id]');if(save){e.preventDefault();e.stopPropagation();toggleSave(save.dataset.saveId);return}const master=e.target.closest('[data-master-id]');if(master){e.preventDefault();e.stopPropagation();toggleMastered(master.dataset.masterId);return}const sp=e.target.closest('[data-speak]');if(sp){e.preventDefault();e.stopPropagation();speak(sp.dataset.speak);return}const fr=e.target.closest('[data-toggle-french]');if(fr){e.preventDefault();fr.closest('.term-card')?.querySelectorAll('.fr').forEach(x=>x.hidden=!x.hidden);return}const focus=e.target.closest('[data-focus-id]');if(focus){const v=VOCABULARY.find(x=>x.id===focus.dataset.focusId);if(v)focusTerm(v);return}const go=e.target.closest('[data-go]');if(go){showPage(go.dataset.go)}})}



