let sprintSteps=[],sprintIndex=0,sprintDomain='18',sprintReviewIds=[],sprintPracticeCorrect=0,sprintPracticeTotal=0,sprintCaseSuccess=false,sprintStepLocked=false;
function chooseSprintWords(ch){let pool=planPool(ch,8);if(pool.length<5){const more=shuffle(VOCABULARY.filter(v=>v.chapter===ch&&!pool.some(x=>x.id===v.id)));pool=[...pool,...more].slice(0,5)}return pool.slice(0,5)}
function buildSprint(ch){const words=chooseSprintWords(ch),caseItem=shuffle(CLINICAL_CASES.filter(c=>c.chapter===ch))[0]||CLINICAL_CASES[0];return[{kind:'flash',v:words[0]},{kind:'flash',v:words[1]},{kind:'practice',v:words[2],mode:'definition'},{kind:'practice',v:words[3],mode:practiceEligible([words[3]],'cloze').length?'cloze':'french'},{kind:'case',caseItem,v:words[4]}]}
function startFiveMinuteSprint(ch=null){sprintDomain=ch||recommendedChapter();sprintSteps=buildSprint(sprintDomain);sprintIndex=0;sprintReviewIds=[];sprintPracticeCorrect=0;sprintPracticeTotal=0;sprintCaseSuccess=false;sprintStepLocked=false;showPage('sprint');renderSprintStep()}
function sprintNext(){sprintIndex++;sprintStepLocked=false;renderSprintStep()}
function updateSprintBar(){const done=Math.min(sprintIndex,sprintSteps.length),shown=Math.min(sprintIndex+1,sprintSteps.length);$('#sprintStepLabel').textContent=sprintIndex>=sprintSteps.length?'Complete':`Step ${shown} of ${sprintSteps.length}`;$('#sprintDomainLabel').textContent=PROGRESS_DOMAINS[sprintDomain]?.name||'Mixed vocabulary';$('#sprintTrack').style.width=`${Math.round(done/sprintSteps.length*100)}%`}
function sprintFlashRate(v,rating){if(sprintStepLocked)return;sprintStepLocked=true;const previous=flashMeta(v.id),delta=rating==='got'?1:-1;flashStats[v.id]={score:Math.max(-5,Math.min(5,(previous.score||0)+delta)),lastRating:rating==='got'?'got':'hard',ratings:(previous.ratings||0)+1,again:previous.again||0,hard:(previous.hard||0)+(rating==='got'?0:1),got:(previous.got||0)+(rating==='got'?1:0),updated:Date.now()};if(rating!=='got'&&!sprintReviewIds.includes(v.id))sprintReviewIds.push(v.id);saveFlashStats();flashPersistMastery(v,rating==='got'?'got':'hard');$('#sprintRatingActions').innerHTML=`<button class="primary-action" id="sprintContinue">Next →</button>`;$('#sprintContinue').onclick=sprintNext}
function renderSprintFlash(step){const v=step.v;$('#sprintBox').innerHTML=`<article class="sprint-card"><span class="sprint-kind">🧠 Flashcard</span><h3>Quick retrieval</h3><div class="sprint-flash-face"><div class="term">${esc(v.term)}</div><div class="ipa">${esc(v.ipa)}</div><button data-speak="${esc(v.term)}">🔊 Listen</button></div><div class="sprint-actions"><button id="sprintReveal" class="primary-action">Reveal meaning</button></div><div id="sprintRevealBox"></div></article>`;$('#sprintReveal').onclick=()=>{$('#sprintReveal').hidden=true;$('#sprintRevealBox').innerHTML=`<div class="sprint-reveal"><h4>${esc(v.french)}</h4><p>${esc(v.levels.B1||v.levels.B2||v.levels.A2||'')}</p><p><em>${esc(v.examples?.B1||v.examples?.B2||v.examples?.A2||'')}</em></p></div><div class="sprint-actions" id="sprintRatingActions"><button id="sprintNeedsReview">↻ Needs another look</button><button id="sprintGot" class="primary-action">✓ Got it</button></div>`;$('#sprintNeedsReview').onclick=()=>sprintFlashRate(v,'review');$('#sprintGot').onclick=()=>sprintFlashRate(v,'got')}}
function renderSprintPractice(step){const v=step.v,q=practiceQuestionData(v,step.mode,VOCABULARY.filter(x=>x.chapter===sprintDomain));$('#sprintBox').innerHTML=`<article class="sprint-card"><span class="sprint-kind">⚡ Quick question</span><h3>${esc(PRACTICE_MODES[step.mode].prompt)}</h3><div class="practice-clue ${step.mode==='cloze'?'practice-cloze':''}">${q.html?q.lead:esc(q.lead)}</div><fieldset class="sprint-options"><legend class="sr-only">Answer options</legend>${q.options.map((o,i)=>`<label class="sprint-option"><input type="radio" name="sprintAnswer" value="${esc(o.value)}"><span class="sprint-option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o.label)}</span></label>`).join('')}</fieldset><div class="sprint-actions"><button id="sprintCheck" class="primary-action">Check answer</button></div><div id="sprintFeedback"></div></article>`;$('#sprintCheck').onclick=()=>{if(sprintStepLocked)return;const picked=$('input[name=sprintAnswer]:checked');if(!picked)return toast('Choose an answer first');sprintStepLocked=true;sprintPracticeTotal++;const correct=picked.value===q.answer;if(correct)sprintPracticeCorrect++;else if(!sprintReviewIds.includes(v.id))sprintReviewIds.push(v.id);$$('.sprint-option').forEach(l=>{const input=$('input',l);l.classList.toggle('correct',input.value===q.answer);if(input.checked&&input.value!==q.answer)l.classList.add('wrong');input.disabled=true});$('#sprintFeedback').innerHTML=`<div class="sprint-reveal"><h4>${correct?'✓ Nice one':'↻ Worth revisiting'}</h4><p>${correct?`${esc(v.term)} · ${esc(v.french)}`:`The answer is <b>${esc(q.answerLabel)}</b> · ${esc(v.french)}`}</p></div><div class="sprint-actions"><button id="sprintContinue" class="primary-action">Next →</button></div>`;$('#sprintContinue').onclick=sprintNext}}
function caseTermChoices(c){const correct=c.keyTerms.slice(0,2),wrong=c.distractors.slice(0,2);return{correct,choices:shuffle([...correct,...wrong])}}
function renderSprintCase(step){const c=step.caseItem,data=caseTermChoices(c);$('#sprintBox').innerHTML=`<article class="sprint-card"><span class="sprint-kind">🩺 Clinical challenge</span><h3>Pick the two most useful terms.</h3><div class="sprint-case"><div class="sprint-patient"><span>${esc(c.patient)} · ${esc(c.setting)}</span><h4>${esc(c.title)}</h4><p>${esc(c.summary)}</p><ul>${c.observations.slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><p><strong>Which two terms best help you describe this situation?</strong></p><fieldset class="sprint-options"><legend class="sr-only">Choose two terms</legend>${data.choices.map((term,i)=>`<label class="sprint-option"><input type="checkbox" name="sprintCaseAnswer" value="${esc(term)}"><span class="sprint-option-letter">${String.fromCharCode(65+i)}</span><span>${esc(term)}</span></label>`).join('')}</fieldset><div class="sprint-actions"><button id="sprintCaseCheck" class="primary-action">Check my choices</button></div><div id="sprintCaseFeedback"></div></div></div></article>`;$('#sprintCaseCheck').onclick=()=>{if(sprintStepLocked)return;const picked=$$('input[name=sprintCaseAnswer]:checked').map(x=>x.value);if(picked.length!==2)return toast('Choose exactly two terms');sprintStepLocked=true;const ok=data.correct.every(x=>picked.includes(x))&&picked.every(x=>data.correct.includes(x));sprintCaseSuccess=ok;data.correct.forEach(term=>{const v=VOCABULARY.find(x=>x.term.toLowerCase()===term.toLowerCase());if(!ok&&v&&!sprintReviewIds.includes(v.id))sprintReviewIds.push(v.id)});$$('.sprint-option').forEach(l=>{const input=$('input',l),isCorrect=data.correct.includes(input.value);l.classList.toggle('correct',isCorrect);if(input.checked&&!isCorrect)l.classList.add('wrong');input.disabled=true});$('#sprintCaseFeedback').innerHTML=`<div class="sprint-model"><h4>${ok?'✓ Good clinical vocabulary choices':'↻ Useful terms to keep active'}</h4><p><b>${esc(data.correct.join(' + '))}</b></p><p>${esc(c.model)}</p></div><div class="sprint-actions"><button id="sprintFinish" class="primary-action">Finish my boost →</button></div>`;$('#sprintFinish').onclick=sprintNext}}
function finishSprint(){updateSprintBar();const reviewed=sprintReviewIds.map(vocabularyById).filter(Boolean);let h=loadArray(STORE.sprintHistory).filter(x=>x&&typeof x==='object');h.unshift({ts:Date.now(),chapter:sprintDomain,reviewIds:[...sprintReviewIds],practiceCorrect:sprintPracticeCorrect,practiceTotal:sprintPracticeTotal,caseSuccess:sprintCaseSuccess});h=h.slice(0,20);localStorage.setItem(STORE.sprintHistory,JSON.stringify(h));$('#sprintBox').innerHTML=`<section class="sprint-card sprint-summary"><div class="sprint-summary-burst">✨</div><span class="eyebrow">Five-minute boost complete</span><h3>Done. Useful beats endless.</h3><div class="sprint-summary-grid"><div><strong>2</strong><span>flashcards</span></div><div><strong>${sprintPracticeCorrect}/${sprintPracticeTotal}</strong><span>quick questions</span></div><div><strong>${sprintCaseSuccess?'✓':'↻'}</strong><span>clinical challenge</span></div></div>${reviewed.length?`<div class="practice-missed-box"><h4>Keep these moving</h4><div class="practice-missed-chips">${reviewed.map(v=>`<button data-focus-id="${esc(v.id)}">${esc(v.term)}</button>`).join('')}</div></div>`:'<p>Nothing was added to your review list in this boost 🎉</p>'}<div class="sprint-actions"><button id="sprintAgain" class="primary-action">↻ Another 5-minute boost</button>${reviewed.length?'<button id="saveSprintReview">♡ Save review words</button>':''}<button id="sprintProgress">📈 Back to My Progress</button></div></section>`;$('#sprintAgain').onclick=()=>startFiveMinuteSprint(sprintDomain);$('#saveSprintReview')?.addEventListener('click',()=>{reviewed.forEach(v=>{if(!notebook.includes(v.id))notebook.push(v.id);mastered=mastered.filter(id=>id!==v.id)});saveNotebookState();toast(`${reviewed.length} word${reviewed.length===1?'':'s'} saved for review ♥`)});$('#sprintProgress').onclick=()=>showPage('progress')}
function renderSprintStep(){updateSprintBar();if(sprintIndex>=sprintSteps.length)return finishSprint();const step=sprintSteps[sprintIndex];if(step.kind==='flash')renderSprintFlash(step);else if(step.kind==='practice')renderSprintPractice(step);else renderSprintCase(step)}
function initSprint(){$('#exitSprint')?.addEventListener('click',()=>showPage('progress'))}

/* V8 · PWA installation, offline status and updates */
let deferredInstallPrompt=null;
function isStandalone(){return window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true}
function setConnectionStatus(){const el=$('#connectionStatus');if(!el)return;const online=navigator.onLine;el.classList.toggle('is-online',online);el.classList.toggle('is-offline',!online);el.innerHTML=`<span aria-hidden="true">●</span> ${online?'Online':'Offline'}`;el.title=online?'Connected. The app is also available offline after it has been cached.':'Offline mode. Cached learning content remains available.'}
function setInstalledUI(){const installed=isStandalone();const card=$('#installCard'),main=$('#installApp'),header=$('#headerInstallApp');if(card)card.classList.toggle('is-installed',installed);if(installed){if(main){main.textContent='✓ App installed';main.disabled=true}if(header)header.hidden=true;const title=$('#installTitle');if(title)title.textContent='Speech Therapy English is installed on this device.'}else{if(main){main.textContent='📲 Install this app';main.disabled=false}if(header)header.hidden=false}}
async function requestInstall(){if(deferredInstallPrompt){deferredInstallPrompt.prompt();const choice=await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;if(choice?.outcome==='accepted'){toast('App installation started ✓')}else{toast('Installation cancelled')}setInstalledUI();return}const help=$('#installHelpPanel');if(help){help.hidden=false;help.scrollIntoView({behavior:st.motion?'auto':'smooth',block:'nearest'})}}
function showUpdateBanner(){const b=$('#updateBanner');if(b)b.hidden=false}
function initPWA(){
  setConnectionStatus();setInstalledUI();
  window.addEventListener('online',()=>{setConnectionStatus();toast('Back online ✓')});
  window.addEventListener('offline',()=>{setConnectionStatus();toast('Offline mode — cached content stays available')});
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;setInstalledUI()});
  window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;setInstalledUI();toast('Speech Therapy English installed ✓')});
  $('#installApp')?.addEventListener('click',requestInstall);$('#headerInstallApp')?.addEventListener('click',requestInstall);
  $('#installHelp')?.addEventListener('click',()=>{const p=$('#installHelpPanel');if(!p)return;p.hidden=!p.hidden;$('#installHelp').textContent=p.hidden?'How to install':'Hide instructions'});
  $('#reloadUpdate')?.addEventListener('click',()=>location.reload());$('#dismissUpdate')?.addEventListener('click',()=>{$('#updateBanner').hidden=true});
  if('serviceWorker' in navigator){
    navigator.serviceWorker.register('./service-worker.js').then(reg=>{
      reg.update().catch(()=>{});
      reg.addEventListener('updatefound',()=>{const worker=reg.installing;if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdateBanner()})});
    }).catch(err=>console.warn('Service worker registration failed:',err));
  }
}
